# Value object: immutable, equality by value
from dataclasses import dataclass

@dataclass(frozen=True)
class Money:
    amount: int   # cents, to avoid float rounding
    currency: str

    def add(self, other: "Money") -> "Money":
        if self.currency != other.currency:
            raise ValueError("currency mismatch")
        return Money(self.amount + other.amount, self.currency)


# Entity: identity via id, behavior enforces invariants
class Subscription:
    def __init__(self, id: str, status: str, price: Money):
        self.id = id
        self.status = status
        self.price = price

    def pause(self, until) -> None:
        if self.status == "final_billing_cycle":
            raise ValueError("cannot pause during the final billing cycle")
        self.status = "paused"

    def __eq__(self, other) -> bool:
        return isinstance(other, Subscription) and self.id == other.id
```

`Money` is frozen and compares by value; `Subscription` compares by `id` alone and puts its rule inside `pause()`, not in a caller.
